graphql.query:
mutation ($orgId: Int!, $orgHandler: String!, $projectId: String!) {
  createByocComponent(
    component: {
      name: "container-event"
      displayName: "container-event"
      description: ""
      orgId: $orgId
      orgHandler: $orgHandler
      projectId: $projectId
      labels: ""
      componentType: "byocWebhook"
      port: 80
      oasFilePath: ""
      accessibility: "external"
      byocConfig: {
        dockerfilePath: "ipaas/containerized/containerized-rabbitmq-listener/Dockerfile"
        dockerContext: "ipaas/containerized/containerized-rabbitmq-listener"
        srcGitRepoUrl: "https://github.com/chameerar/choreo-examples"
        srcGitRepoBranch: "main"
      }
      secretRef: ""
    }
  ) {
    id
    organizationId
    projectId
    handle
  }
}

body.raw:
{
    "variables": {
        "org": {
            "orgId": "{{orgUuid}}"
        },
        "projectId": "{{projectId}}"
    },
    "query": "query ($org: OrgFilter!, $projectId: String) {
  listEnvironments(org: $org, projectId: $projectId) {
    id
    externalEnvId
    internalEnvId
    sandboxEnvId
    name
    type
    __typename
  }
}
"
}

{
    "variables": {
        "filter": {
            "from": "2023-06-23T13:11:06.000+05:30",
            "to": "2023-06-30T13:11:06.000+05:30"
        },
        "latencySummaryFilter": {
            "granularity": "1d"
        },
        "granularity": "1d",
        "dataFilter": {
            "orgId": "{{orgUuid}}",
            "environmentIds": [
                "{{devEnvironmentId}}",
                "dev-us-east-azure",
                "sandbox-dev",
                "Dev-Internal"
            ],
            "tenant": "carbon.super",
            "projectId": "{{projectId}}"
        }
    },
    "query": "query ($dataFilter: DataFilter!, $filter: TimeFilter!, $latencySummaryFilter: LatencySummaryFilter!, $granularity: String!) {
  getTotalTraffic(filter: $filter, dataFilter: $dataFilter)
  getOverallLatency(filter: $filter, dataFilter: $dataFilter)
  getTotalErrors(filter: $filter, dataFilter: $dataFilter)
  getLatencySummary(
    filter: $filter
    latencySummaryFilter: $latencySummaryFilter
    dataFilter: $dataFilter
  ) {
    summary {
      timeSpan
      latencyTime
      __typename
    }
    granularity
    __typename
  }
  getSuccessSummary(
    filter: $filter
    dataFilter: $dataFilter
    granularity: $granularity
  ) {
    summary {
      timeSpan
      requestCount
      __typename
    }
    granularity
    __typename
  }
  getErrorSummary(
    filter: $filter
    dataFilter: $dataFilter
    granularity: $granularity
  ) {
    summary {
      timeSpan
      errorCount
      __typename
    }
    granularity
    __typename
  }
}
"
}
